            ₹{needWantTotals.Need}
          </div>
        </div>

        {/* WANTS */}
        <div
          style={{
            padding: "18px",
            borderRadius: "18px",

            background: darkMode
              ? "#1e293b"
              : "#f8fafc"
          }}
        >
          <div
            style={{
              fontSize: "13px",
              color: "#94a3b8"
            }}
          >
            Discretionary Spending
          </div>

          <div
            style={{
              marginTop: "6px",
              fontSize: "28px",
              fontWeight: "700",
              color: "#ef4444"
            }}
          >
            {wantPercent}%
          </div>

          <div
            style={{
              marginTop: "4px",
              fontSize: "13px"
            }}
          >
            ₹{needWantTotals.Want}
          </div>
        </div>

      </div>

      {/* AI ANALYSIS */}
      <div
        style={{
          marginTop: "24px",

          padding: "18px",

          borderRadius: "18px",

          background: darkMode
            ? "rgba(79,109,245,0.12)"
            : "#eef2ff",

          border: "1px solid rgba(79,109,245,0.15)"
        }}
      >

        <div
          style={{
            fontWeight: "700",
            marginBottom: "10px"
          }}
        >
          AI Behavioral Insight
        </div>

        <div
          style={{
            fontSize: "14px",
            lineHeight: "1.8",
            color: darkMode
              ? "#d1d5db"
              : "#374151"
          }}
        >

          {wantPercent > 60 &&
            "Your spending pattern indicates impulsive discretionary behavior. Reducing non-essential purchases can significantly improve long-term savings."}

          {wantPercent <= 60 &&
            wantPercent > 35 &&
            "Your spending behavior is moderately balanced. Some discretionary expenses are present but remain within manageable levels."}

          {wantPercent <= 35 &&
            "Excellent financial discipline detected. Most of your spending is focused on essential categories, indicating strong budgeting habits."}

        </div>

      </div>

    </div>

  </div>

</div>

{/* PREMIUM MONTHLY TREND */}
<div
  style={{
    background: darkMode
      ? "linear-gradient(145deg,#0f172a,#111827)"
      : "#ffffff",

    padding: "28px",
    borderRadius: "24px",
    marginTop: "24px",

    border: darkMode
      ? "1px solid rgba(255,255,255,0.06)"
      : "1px solid #e5e7eb",

    boxShadow: darkMode
      ? "0 10px 40px rgba(0,0,0,0.45)"
      : "0 10px 30px rgba(0,0,0,0.08)"
  }}
>

  {/* HEADER */}
  <div
    style={{
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
      marginBottom: "24px"
    }}
  >

    <div>
      <h3
        style={{
          fontSize: "22px",
          fontWeight: "700",
          marginBottom: "6px"
        }}
      >
        Monthly Spending Trend
      </h3>

      <p
        style={{
          fontSize: "13px",
          color: darkMode ? "#94a3b8" : "#6b7280"
        }}
      >
        Smart tracking of Need vs Want expenses
      </p>
    </div>

    {/* MINI ANALYTICS BADGE */}
    <div
      style={{
        padding: "10px 16px",
        borderRadius: "14px",

        background:
          wantPercent > 50
            ? "rgba(239,68,68,0.12)"
            : "rgba(34,197,94,0.12)",

        color:
          wantPercent > 50
            ? "#ef4444"
            : "#22c55e",

        fontWeight: "600",
        fontSize: "13px"
      }}
    >
      {wantPercent > 50
        ? "High Want Spending"
        : "Healthy Spending"}
    </div>
  </div>

  {/* CHART */}
  <ResponsiveContainer width="100%" height={380}>
    <BarChart
      data={monthlyNeedWantData}
      barGap={8}
    >

      {/* GRADIENTS */}
      <defs>

        <linearGradient
          id="needGradient"
          x1="0"
          y1="0"
          x2="0"
          y2="1"
        >
          <stop
            offset="0%"
            stopColor="#22c55e"
          />
          <stop
            offset="100%"
            stopColor="#16a34a"
          />
        </linearGradient>

        <linearGradient
          id="wantGradient"
          x1="0"
          y1="0"
          x2="0"
          y2="1"
        >
          <stop
            offset="0%"
            stopColor="#ef4444"
          />
          <stop
            offset="100%"
            stopColor="#dc2626"
          />
        </linearGradient>

      </defs>

      {/* GRID */}
      <CartesianGrid
        strokeDasharray="4 4"
        vertical={false}
        stroke={
          darkMode
            ? "rgba(255,255,255,0.08)"
            : "#e5e7eb"
        }
      />

      {/* X AXIS */}
      <XAxis
        dataKey="month"
        tick={{
          fill: darkMode
            ? "#94a3b8"
            : "#6b7280",
          fontSize: 12
        }}
        axisLine={false}
        tickLine={false}
      />

      {/* Y AXIS */}
      <YAxis
        tick={{
          fill: darkMode
            ? "#94a3b8"
            : "#6b7280",
          fontSize: 12
        }}
        axisLine={false}
        tickLine={false}
      />

      {/* TOOLTIP */}
      <Tooltip
        cursor={{
          fill: "rgba(255,255,255,0.03)"
        }}

        contentStyle={{
          borderRadius: "16px",
          border: "none",

          background: darkMode
            ? "#111827"
            : "#ffffff",

          boxShadow:
            "0 10px 30px rgba(0,0,0,0.25)",

          padding: "12px"
        }}
      />

      {/* LEGEND */}
      <Legend
        wrapperStyle={{
          paddingTop: "18px"
        }}
      />

      {/* NEED BAR */}
      <Bar
        dataKey="Need"
        fill="url(#needGradient)"
        radius={[12, 12, 0, 0]}
        barSize={24}
      />

      {/* WANT BAR */}
      <Bar
        dataKey="Want"
        fill="url(#wantGradient)"
        radius={[12, 12, 0, 0]}
        barSize={24}
      />

    </BarChart>
  </ResponsiveContainer>

  {/* SMART FOOTER */}
  <div
    style={{
      marginTop: "18px",

      display: "flex",
      justifyContent: "space-between",

      flexWrap: "wrap",
      gap: "14px"
    }}
  >

    <div
      style={{
        padding: "14px",
        borderRadius: "14px",

        background: darkMode
          ? "#1e293b"
          : "#f8fafc",

        flex: 1
      }}
    >
      <div
        style={{
          fontSize: "12px",
          color: "#94a3b8"
        }}
      >
        Total Needs
      </div>

      <div
        style={{
          marginTop: "4px",
          fontSize: "20px",
          fontWeight: "700",
          color: "#22c55e"
        }}
      >
        ₹{needWantTotals.Need}
      </div>
    </div>

    <div
      style={{
        padding: "14px",
        borderRadius: "14px",

        background: darkMode
          ? "#1e293b"
          : "#f8fafc",

        flex: 1
      }}
    >
      <div
        style={{
          fontSize: "12px",
          color: "#94a3b8"
        }}
      >
        Total Wants
      </div>

      <div
        style={{
          marginTop: "4px",
          fontSize: "20px",
          fontWeight: "700",
          color: "#ef4444"
        }}
      >
        ₹{needWantTotals.Want}
      </div>
    </div>

  </div>

</div>


{/* SMART AI RECOMMENDATION ENGINE */}

<div
  style={{
    marginTop: "24px",

    background: darkMode
      ? "linear-gradient(145deg,#0f172a,#111827)"
      : "#ffffff",

    padding: "30px",

    borderRadius: "24px",

    border: darkMode
      ? "1px solid rgba(255,255,255,0.06)"
      : "1px solid #e5e7eb",

    boxShadow: darkMode
      ? "0 10px 40px rgba(0,0,0,0.45)"
      : "0 10px 30px rgba(0,0,0,0.08)"
  }}
>

  {/* HEADER */}
  <div
    style={{
      display: "flex",
      justifyContent: "space-between",
      alignItems: "center",
      marginBottom: "24px",
      flexWrap: "wrap",
      gap: "14px"
    }}
  >

    <div>
      <h3
        style={{
          fontSize: "24px",
          fontWeight: "700"
        }}
      >
        AI Recommendation Engine
      </h3>

      <p
        style={{
          fontSize: "13px",
          color: darkMode
            ? "#94a3b8"
            : "#6b7280"
        }}
      >
        Personalized financial intelligence
      </p>
    </div>

  </div>

  {/* ACHIEVEMENTS */}
  {achievements.length > 0 && (

    <div
      style={{
        display: "flex",
        gap: "12px",
        flexWrap: "wrap",
        marginBottom: "24px"
      }}
    >

      {achievements.map((a, idx) => (

        <div
          key={idx}
          style={{
            padding: "10px 16px",

            borderRadius: "14px",

            background: darkMode
              ? "#1e293b"
              : "#f8fafc",

            fontSize: "13px",
            fontWeight: "600"
          }}
        >
          {a}
        </div>

      ))}

    </div>

  )}

  {/* RECOMMENDATION CARDS */}
  <div
    style={{
      display: "grid",
      gap: "18px"
    }}
  >

    {recommendations.map((rec, idx) => (

      <div
        key={idx}
        style={{
          padding: "22px",

          borderRadius: "20px",

          background: darkMode
            ? "#1e293b"
            : "#f8fafc",

          border:
            rec.type === "warning"
              ? "1px solid rgba(239,68,68,0.25)"
              : rec.type === "success"
              ? "1px solid rgba(34,197,94,0.25)"
              : "1px solid rgba(79,109,245,0.18)"
        }}
      >

        {/* TOP */}
        <div
          style={{
            display: "flex",
            justifyContent: "space-between",
            alignItems: "center",
            marginBottom: "12px"
          }}
        >

          <div
            style={{
              fontSize: "18px",
              fontWeight: "700"
            }}
          >
            {rec.title}
          </div>

          <div
            style={{
              fontSize: "12px",

              padding: "6px 10px",

              borderRadius: "10px",

              background:
                rec.type === "warning"
                  ? "rgba(239,68,68,0.12)"
                  : rec.type === "success"
                  ? "rgba(34,197,94,0.12)"
                  : "rgba(79,109,245,0.12)"
            }}
          >
            {rec.confidence}
          </div>

        </div>

        {/* DESCRIPTION */}
        <div
          style={{
            fontSize: "14px",
            lineHeight: "1.8",

            color: darkMode
              ? "#d1d5db"
              : "#374151"
          }}
        >
          {rec.description}
        </div>

        {/* IMPACT */}
        <div
          style={{
            marginTop: "14px",

            padding: "12px",

            borderRadius: "14px",

            background: darkMode
              ? "#0f172a"
              : "#ffffff",

            fontSize: "13px",

            fontWeight: "600"
          }}
        >
          💡 {rec.impact}
        </div>

      </div>

    ))}

  </div>

</div>

{/* AI CHATBOT */}

<div
  style={{
    marginTop: "25px",
    background: darkMode ? "#111827" : "#ffffff",
    borderRadius: "20px",
    padding: "24px",
    boxShadow: darkMode
      ? "0 4px 20px rgba(0,0,0,0.4)"
      : "0 4px 20px rgba(0,0,0,0.08)"
  }}
>
  <h3>🤖 Financial AI Chatbot</h3>

  <div
    style={{
      height: "300px",
      overflowY: "auto",
      marginTop: "15px",
      padding: "10px",
      borderRadius: "12px",
      background: darkMode
        ? "#0f172a"
        : "#f9fafb"
    }}
  >
    {chatMessages.map((msg, index) => (

      <div
        key={index}
        style={{
          textAlign:
            msg.sender === "user"
              ? "right"
              : "left",

          marginBottom: "10px"
        }}
      >
        <span
          style={{
            display: "inline-block",
            padding: "10px 14px",
            borderRadius: "12px",

            background:
              msg.sender === "user"
                ? "#4f6df5"
                : darkMode
                ? "#1e293b"
                : "#e5e7eb",

            color:
              msg.sender === "user"
                ? "#fff"
                : darkMode
                ? "#fff"
                : "#111"
          }}
        >
          {msg.text}
        </span>
      </div>

    ))}
  </div>

  <div
    style={{
      display: "flex",
      gap: "10px",
      marginTop: "15px"
    }}
  >
    <input
      value={userInput}
      onChange={(e) =>
        setUserInput(e.target.value)
      }
      placeholder="Ask about spending, savings, risk..."
      style={{
        flex: 1,
        padding: "12px",
        borderRadius: "10px",
        border: "1px solid #d1d5db"
      }}
    />

    <button
      onClick={handleSendMessage}
      style={{
        background: "#4f6df5",
        color: "#fff",
        border: "none",
        padding: "12px 20px",
        borderRadius: "10px",
        cursor: "pointer"
      }}
    >
      Send
    </button>
  </div>
</div>

      {/* INSIGHTS LIST */}
      <div className="card" style={{ marginTop: "20px" }}>
        <h3>Detailed Insights</h3>
        <div style={{ marginBottom: "15px" }}>

  {needPercent >= 70 && (
    <p>
      ✅ Excellent financial discipline detected.
    </p>
  )}

  {wantPercent >= 50 && (
    <p>
      ⚠️ High discretionary spending detected.
    </p>
  )}

  {disciplineScore < 60 && (
    <p>
      🚨 Your financial discipline score is low.
    </p>
  )}

  {disciplineScore >= 80 && (
    <p>
      💡 Your spending behavior appears balanced.
    </p>
  )}

</div>

        {insights.length > 0 ? (
          insights.map((i, idx) => (
            <div
              key={idx}
              style={{
                padding: "10px",
                borderRadius: "8px",
                marginBottom: "8px",
                background: darkMode ? "#1f2937" : "#f9fafb"
              }}
            >
              {i}
            </div>
          ))
        ) : (
          <p>No insights available</p>
        )}
      </div>

    </div>
  );
}

export default InsightsPage;
